#!/usr/bin/env bash
# Majorité, étape 2 — le formulaire de création d'un compte.
# - Statut d'abord : Administrateur, Instructeur, Bureau (majeur d'office) ou simple membre ; autres groupes facultatifs ;
# - cours : pour un simple membre, un cours enfants/ados grise les autres (sauf Tous publics) ;
# - majorité : la date de naissance, facultative, décide ; sinon Majeur/Mineur ;
# - mineur : parent avec prénom, nom, qualité, e-mail, téléphone ; sa date de naissance n'est plus obligatoire ;
# - guide admin et tutoriel à jour ; e2e creation-compte. Pas de migration.
# Prérequis : apply-majorite-1-groupes-systeme.sh.
# Usage (racine du repo) : bash apply-majorite-2-creation-compte.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/admin/users/forms/CreateUserForm.tsx" 2>/dev/null | grep -qF "CreationLegalFields"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "enum SystemGroupKind" "prisma/schema.prisma" 2>/dev/null || { echo "lancez d'abord apply-majorite-1-groupes-systeme.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/creer-un-utilisateur.mdx" "apps/web/src/app/(admin)/dashboard/users/create/page.tsx" "apps/web/src/features/admin/users/courses/CoursesPicker.tsx" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/tours/definitions/admin.users.create.ts" "packages/backend/src/modules/users/legalInfo.ts" "packages/backend/src/modules/users/router.ts")
CREATED=("apps/web/src/features/admin/users/legal/CreationLegalFields.tsx" "e2e/creation-compte.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "CreationLegalFields" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/users/legal"
